\"\"\"
A minimal, standard-library-only client for OpenAI's Responses API.

Usage::

    import openai_client

    client = openai_client.OpenAI(api_key=\"sk-...\")  # or set OPENAI_API_KEY
    response = client.create(\"What is the capital of France?\")
    print(response.output_text)

    # Streaming
    for event in client.create(\"Tell me a short story.\", stream=True):
        print(event.get(\"text\", \"\"), end=\"\", flush=True)
\"\"\"

from __future__ import annotations

import json
import os
import ssl
import urllib.error
import urllib.request
from typing import Any, Iterator, Optional

__all__ = [\"OpenAI\", \"APIError\", \"APIStatusError\", \"AuthenticationError\"]

DEFAULT_BASE_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4o-mini\"

# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------


class APIError(Exception):
    \"\"\"Base exception for API errors.\"\"\"


class APIStatusError(APIError):
    \"\"\"Raised when the API returns a non-2xx status.\"\"\"

    def __init__(self, message: str, status_code: int, body: dict | None = None) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.body = body or {}


class AuthenticationError(APIStatusError):
    \"\"\"Raised on 401 responses – usually a bad or missing API key.\"\"\"


# ---------------------------------------------------------------------------
# Response wrapper
# ---------------------------------------------------------------------------


class Response:
    \"\"\"Wraps a Responses-API payload with convenience accessors.\"\"\"

    def __init__(self, data: dict[str, Any]) -> None:
        self._data = data

    @property
    def id(self) -> str:
        \"\"\"The unique response ID, e.g. "'``resp_...``."""
        return self._data.get("id", "")

    @property
    def model(self) -> str:
        return self._data.get("model", "")

    @property
    def output(self) -> list[dict[str, Any]]:
        return self._data.get("output", [])

    @property
    def output_text(self) -> str:
        """The concatenated text from all ``message`` output items."""
        parts: list[str] = []
        for item in self.output:
            if item.get("type") == "message":
                for content in item.get("content", []):
                    if content.get("type") == "output_text":
                        parts.append(content.get("text", ""))
        return "".join(parts)

    @property
    def usage(self) -> dict[str, Any]:
        return self._data.get("usage", {})

    @property
    def raw(self) -> dict[str, Any]:
        """The complete JSON response dict."""
        return self._data

    def __repr__(self) -> str:
        return f"Response(id={self.id!r}, model={self.model!r})"


# ---------------------------------------------------------------------------
# Client
# ---------------------------------------------------------------------------


class OpenAI:
    """Synchronous client for the OpenAI Responses API.

    Parameters
    ----------
    api_key: API key.  If *None*, reads ``OPENAI_API_KEY`` from the
        environment.
    base_url: Override the Responses API endpoint.
    default_model: Model used when ``create()`` is called without a
        ``model`` argument.
    timeout: HTTP timeout in seconds (connect + read).
    """

    def __init__(
        self,
        api_key: str | None = None,
        base_url: str = DEFAULT_BASE_URL,
        default_model: str = DEFAULT_MODEL,
        timeout: int = 60,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        self.base_url = base_url.rstrip("/")
        self.default_model = default_model
        self.timeout = timeout

        tls_ctx = ssl.create_default_context()
        self._ssl_context = tls_ctx

    # -- helpers -----------------------------------------------------------

    def _build_request(self, path: str, payload: dict[str, Any]) -> urllib.request.Request:
        body = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            url=f"{self.base_url}{path}",
            data=body,
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "text/event-stream, application/json",
            },
            method="POST",
        )
        return req

    def _handle_response(self, resp, stream: bool) -> Response | Iterator[dict[str, Any]]:
        if stream:
            return self._read_sse(resp)
        raw_body = resp.read().decode("utf-8")
        data = json.loads(raw_body)
        return Response(data)

    def _read_sse(self, resp) -> Iterator[dict[str, Any]]:
        """Yield dicts parsed from each SSE ``data:`` line."""
        buffer = b""
        while True:
            chunk = resp.read(4096)
            if not chunk:
                break
            buffer += chunk
            while b"'"\\n\" in buffer:
                line, buffer = buffer.split(b\"\\n\", 1)
                decoded = line.decode(\"utf-8\").strip()
                if decoded.startswith(\"data: \"):
                    payload = decoded[6:]
                    if payload == \"[DONE]\":
                        return
                    try:
                        yield json.loads(payload)
                    except json.JSONDecodeError:
                        continue

    # -- public API --------------------------------------------------------

    def create(
        self,
        input: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
        top_p: float | None = None,
        stream: bool = False,
        **extra: Any,
    ) -> Response | Iterator[dict[str, Any]]:
        \"\"\"Send a text prompt to the Responses API.

        Parameters
        ----------
        input: The user prompt string.  Also accepted as the first positional
            argument.
        model: Model name.  Defaults to "'``self.default_model``.
        instructions: System-level instructions (like a system prompt).
        temperature: Sampling temperature (0–2).
        max_output_tokens: Cap on completion tokens.
        top_p: Nucleus sampling parameter (0–1).
        stream: When *True*, returns an iterator of event dicts.
        **extra: Additional parameters forwarded to the API body.

        Returns
        -------
        A :class:`Response` object, or an iterator of event dicts when
        ``stream=True``.
        """
        if self.api_key is None:
            raise AuthenticationError(
                "No API key provided.  Set OPENAI_API_KEY or pass api_key=...",
                status_code=401,
            )

        payload: dict[str, Any] = {
            "model": model or self.default_model,
            "input": input,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if top_p is not None:
            payload["top_p"] = top_p
        if stream:
            payload["stream"] = True
        payload.update(extra)

        req = self._build_request("", payload)

        try:
            resp = urllib.request.urlopen(req, timeout=self.timeout, context=self._ssl_context)
        except urllib.error.HTTPError as exc:
            return self._raise_http_error(exc)
        except urllib.error.URLError as exc:
            raise APIError(f"Connection / URL error: {exc.reason}") from exc
        except OSError as exc:
            raise APIError(f"Network error: {exc}") from exc

        return self._handle_response(resp, stream=stream)

    def _raise_http_error(self, exc: urllib.error.HTTPError) -> None:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except Exception:
            body = None
        msg = f"{exc.code} {exc.reason}"
        if isinstance(body, dict):
            error_info = body.get("error", {})
            api_msg = error_info.get("message", "")
            if api_msg:
                msg = f"{msg}: {api_msg}"
        if exc.code == 401:
            raise AuthenticationError(msg, status_code=exc.code, body=body)
        raise APIStatusError(msg, status_code=exc.code, body=body)

    # -- convenience -------------------------------------------------------

    def __call__(self, prompt: str, **kwargs: Any) -> Response | Iterator[dict[str, Any]]:
        """``client("some prompt")`` is shorthand for ``client.create("some prompt")``."""
        return self.create(prompt, **kwargs)


# ---------------------------------------------------------------------------
# Module-level convenience
# ---------------------------------------------------------------------------


_default_client: OpenAI | None = None


def _get_default_client() -> OpenAI:
    global _default_client
    if _default_client is None:
        _default_client = OpenAI()
    return _default_client


def create(
    input: str,
    *,
    model: str | None = None,
    instructions: str | None = None,
    temperature: float | None = None,
    max_output_tokens: int | None = None,
    top_p: float | None = None,
    stream: bool = False,
    **extra: Any,
) -> Response | Iterator[dict[str, Any]]:
    """Convenience function that uses a module-level default client."""
    return _get_default_client().create(
        input,
        model=model,
        instructions=instructions,
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        top_p=top_p,
        stream=stream,
        **extra,
    )


# ---------------------------------------------------------------------------
# __main__ – quick smoke-test
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        print("Usage:  python openai_client.py '"\\\"Your prompt here\\\"\", file=sys.stderr)
        sys.exit(1)

    prompt = \" \".join(sys.argv[1:])
    client = OpenAI()
    print(\"[prompt]\", prompt)
    print(\"-\" * 60)
    response = client.create(prompt)
    print(response.output_text)
    if response.usage:
        print(\"-\" * 60)
        print(\"[usage]\", json.dumps(response.usage, indent=2))
